import { env } from '@/lib/env';

let API_BASE: string | undefined;

function getApiBase(): string {
  if (!API_BASE) {
    API_BASE = env.NEXT_PUBLIC_API_URL || '';
  }
  return API_BASE;
}

async function request<T>(input: string, init?: RequestInit): Promise<T> {
  const apiBase = getApiBase();
  const url = apiBase ? `${apiBase}${input}` : input;

  const res = await fetch(url, {
    ...init,
    headers: {
      'Content-Type': 'application/json',
      ...(init?.headers || {}),
    },
  });

  if (!res.ok) {
    const error = (await res.json().catch(() => ({}))) as { error?: string };
    throw new Error(error.error || `Request failed with status ${res.status}`);
  }

  return res.json();
}

export const api = {
  get: <T>(path: string) => request<T>(path),
  post: <T>(path: string, body: unknown) =>
    request<T>(path, { method: 'POST', body: JSON.stringify(body) }),
};

export const contentApi = {
  getVocab: () => api.get<any[]>('/content/vocab'),
  getQuests: () => api.get<any[]>('/content/quests'),
  getQuestTasks: (id: string) => api.get<any[]>(`/content/quests/${id}/tasks`),
  getDialogue: (world: string) => api.get<any>(`/content/dialogues/${world}`),
  getConfig: () => api.get<any[]>('/content/config'),
};

export const userApi = {
  getMe: () => api.get<any>('/auth/me'),
  getProgress: () => api.get<UserProgress>('/user/progress'),
  addXP: (userId: string, xp: number, reason?: string) =>
    api.post<any>('/user/progress/xp', { userId, xp, reason }),
  completeQuestTask: (userId: string, questId: string, taskKey: string) =>
    api.post<any>('/user/progress/quest', { userId, questId, taskKey }),
};

export const chatApi = {
  sendMessage: (body: { npcKey: string; language: 'ar' | 'en'; messages: any[]; gameLocation?: any }) =>
    api.post<any>('/chat', body),
};

export interface UserProgress {
  userId: string;
  xp: number;
  level: number;
  completedQuests: any[];
}
